// Package: ModelContextProtocol --version 1.*

using ModelContextProtocol.Server;

public class CustomerResource(ICustomerRepository repository)
{
    [McpServerResource(UriTemplate = "customer://{id}")]
    public async Task<string> GetAsync(string id, CancellationToken cancellationToken)
    {
        var customer = await repository.GetByIdAsync(id, cancellationToken);
        if (customer is null)
            throw new McpResourceNotFoundException($"Customer '{id}' not found.");

        return JsonSerializer.Serialize(new
        {
            customer.Id,
            customer.Name,
            customer.Tier,
            customer.ActiveSince
        });
    }
}

