using ModelContextProtocol.Server;

[McpServerPrompt(Name = "support_triage")]
public static class SupportTriagePrompt
{
    [McpServerPromptArgument("ticket", "The support ticket text", required: true)]
    [McpServerPromptArgument("customer_tier", "Customer tier such as free, pro, or enterprise", required: false)]
    public static string Build(IReadOnlyDictionary<string, object?> arguments)
    {
        var tier = arguments.GetValueOrDefault("customer_tier")?.ToString() ?? "standard";
        var ticket = arguments.GetValueOrDefault("ticket")?.ToString() ?? "";
        return $"You are a support triage assistant.\nCustomer tier: {tier}\nTicket: {ticket}\nSummarize the issue and suggest next steps.";
    }
}

